```tsx
import "./ProblemTable.css";

export interface ProblemRow {
  title: string;
  pattern: string;
  minutes: number;
  review: string;
  due: boolean;
}

export interface ProblemTableProps {
  rows: readonly ProblemRow[];
}

export function ProblemTable({ rows }: ProblemTableProps) {
  return (
    <div className="problem-table-scroll" role="region" aria-label="Solved problems" tabIndex={0}>
      <table className="problem-table">
        <caption className="sr-only">Solved problems and their next review</caption>
        <thead>
          <tr>
            <th scope="col">Title</th>
            <th scope="col">Pattern</th>
            <th scope="col" className="problem-table-num">Minutes</th>
            <th scope="col">Next review</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <tr key={`${row.title}-${index}`}>
              <th scope="row" className="problem-table-title">{row.title}</th>
              <td>{row.pattern}</td>
              <td className="problem-table-num">{row.minutes}</td>
              <td className={row.due ? "is-due" : undefined}>
                {row.review}
                {row.due ? <span className="sr-only"> (due today)</span> : null}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
```

```css
.problem-table-scroll {
  overflow-x: auto;
  border-radius: 12px;
}

.problem-table {
  width: 100%;
  border-collapse: collapse;
  font-size: clamp(0.875rem, 0.8rem + 0.35vw, 1.05rem);
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.problem-table th,
.problem-table td {
  padding: 0.6em 0.9em;
  text-align: left;
  vertical-align: middle;
  border-bottom: 1px solid var(--hair);
}

.problem-table thead th {
  color: var(--muted);
  font-weight: 600;
  font-size: 0.85em;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-bottom-color: var(--muted);
}

.problem-table tbody th[scope="row"] {
  font-weight: 500;
}

.problem-table .problem-table-num {
  text-align: right;
}

.problem-table td.is-due {
  color: var(--cresyl);
  background: var(--cresyl-wash);
  font-weight: 600;
}

.problem-table tbody tr:hover th,
.problem-table tbody tr:hover td:not(.is-due) {
  background: var(--myelin-wash);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .problem-table * {
    transition: none;
    animation: none;
  }
}

:root[data-motion="reduce"] .problem-table * {
  transition: none;
  animation: none;
}
